// SMDWin — Services/NetworkReader.cs
// Network I/O through NetworkInterface.GetIPv4Statistics() with a correct delta.
// A single data source (not several simultaneous calls), no race conditions.

using System;
using System.Collections.Generic;
using System.Net.NetworkInformation;

namespace SMDWin.Services
{
    /// <summary>Static counter for traffic GENERATED BY THE APP as part of background monitoring (e.g. continuous ping) —
    /// NOT for deliberate bandwidth tests (Speed Test), which must stay visible as real traffic. NetworkReader.Update()
    /// subtracts these bytes from the raw delta measured on the interface before computing KB/s, so the app's own
    /// monitoring does not show up as false "spikes" on the user's traffic chart.</summary>
    public static class NetworkSelfTraffic
    {
        private static long _pendingInBytes;
        private static long _pendingOutBytes;
        private static readonly object _lock = new();

        /// <summary>Called after every ICMP packet sent by background monitoring — standard sizes: request ~60 bytes
        /// (32 payload + 28 IP/ICMP header), reply the same.</summary>
        public static void ReportPingBytes(long outBytes, long inBytes)
        {
            lock (_lock)
            {
                _pendingOutBytes += outBytes;
                _pendingInBytes  += inBytes;
            }
        }

        /// <summary>Consumes (and resets) the bytes accumulated since the last call — NetworkReader.Update() subtracts them
        /// from the raw delta of the current interval.</summary>
        internal static (long outBytes, long inBytes) TakePending()
        {
            lock (_lock)
            {
                var result = (_pendingOutBytes, _pendingInBytes);
                _pendingOutBytes = 0;
                _pendingInBytes  = 0;
                return result;
            }
        }
    }

    public sealed class NetworkAdapterSnapshot
    {
        public string Name        { get; init; } = "";
        public string Description { get; init; } = "";
        public float  DownKBs     { get; init; }
        public float  UpKBs       { get; init; }
        public long   SpeedBps    { get; init; }
        public bool   IsWireless  { get; init; }
    }

    public sealed class NetworkReader
    {
        private class AdapterState
        {
            public string Name        = "";
            public string Description = "";
            public bool   IsWireless;
            public long   Speed;
            public long   PrevIn;
            public long   PrevOut;
            public DateTime PrevTime  = DateTime.MinValue;
        }

        private readonly List<AdapterState> _adapters = new();
        private DateTime _lastEnumTime = DateTime.MinValue;
        private const double EnumIntervalSec = 30.0;

        public float TotalDownKBs { get; private set; }
        public float TotalUpKBs   { get; private set; }
        public IReadOnlyList<NetworkAdapterSnapshot> Adapters { get; private set; }
            = Array.Empty<NetworkAdapterSnapshot>();

        public void Update()
        {
            try
            {
                var now = DateTime.UtcNow;

                if (_adapters.Count == 0 ||
                    (now - _lastEnumTime).TotalSeconds > EnumIntervalSec)
                    EnumerateAdapters();

                float totalDown = 0f, totalUp = 0f;
                var snapshots = new List<NetworkAdapterSnapshot>(_adapters.Count);
                var (selfOutBytes, selfInBytes) = NetworkSelfTraffic.TakePending();

                foreach (var adapter in _adapters)
                {
                    try
                    {
                        // Find the current NIC by name
                        NetworkInterface? nic = null;
                        foreach (var n in NetworkInterface.GetAllNetworkInterfaces())
                        {
                            if (n.Name == adapter.Name)
                            { nic = n; break; }
                        }
                        if (nic == null || nic.OperationalStatus != OperationalStatus.Up) continue;

                        var stats = nic.GetIPv4Statistics();
                        long curIn  = stats.BytesReceived;
                        long curOut = stats.BytesSent;

                        float downKBs = 0f, upKBs = 0f;

                        if (adapter.PrevTime != DateTime.MinValue)
                        {
                            double elapsed = (now - adapter.PrevTime).TotalSeconds;
                            if (elapsed > 0.01)
                            {
                                // Handle counter wrap (on reboot the counters reset to 0)
                                long dIn  = curIn  >= adapter.PrevIn  ? curIn  - adapter.PrevIn  : curIn;
                                long dOut = curOut >= adapter.PrevOut ? curOut - adapter.PrevOut : curOut;

                                dOut = Math.Max(0, dOut - selfOutBytes);
                                dIn  = Math.Max(0, dIn  - selfInBytes);

                                downKBs = (float)(dIn  / 1024.0 / elapsed);
                                upKBs   = (float)(dOut / 1024.0 / elapsed);

                                // Sanity: max ~10 Gbps
                                float maxKBs = adapter.Speed > 0
                                    ? (float)(adapter.Speed / 8.0 / 1024.0) * 1.05f
                                    : 1_250_000f;
                                if (downKBs > maxKBs) downKBs = 0f;
                                if (upKBs   > maxKBs) upKBs   = 0f;
                            }
                        }

                        adapter.PrevIn   = curIn;
                        adapter.PrevOut  = curOut;
                        adapter.PrevTime = now;

                        totalDown += downKBs;
                        totalUp   += upKBs;

                        snapshots.Add(new NetworkAdapterSnapshot
                        {
                            Name        = adapter.Name,
                            Description = adapter.Description,
                            DownKBs     = downKBs,
                            UpKBs       = upKBs,
                            SpeedBps    = adapter.Speed,
                            IsWireless  = adapter.IsWireless
                        });
                    }
                    catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); /* skip an adapter with an error */ }
                }

                TotalDownKBs = totalDown;
                TotalUpKBs   = totalUp;
                Adapters     = snapshots;
            }
            catch (Exception ex)
            {
                _ = System.Threading.Tasks.Task.Run(
                    () => AppLogger.Warning(ex, "NetworkReader.Update"));
            }
        }

        private void EnumerateAdapters()
        {
            _adapters.Clear();
            try
            {
                foreach (var nic in NetworkInterface.GetAllNetworkInterfaces())
                {
                    if (nic.OperationalStatus != OperationalStatus.Up)    continue;
                    if (nic.NetworkInterfaceType == NetworkInterfaceType.Loopback) continue;
                    if (nic.NetworkInterfaceType == NetworkInterfaceType.Tunnel)   continue;

                    _adapters.Add(new AdapterState
                    {
                        Name        = nic.Name,
                        Description = nic.Description,
                        IsWireless  = nic.NetworkInterfaceType == NetworkInterfaceType.Wireless80211,
                        Speed       = Math.Max(0, nic.Speed)
                    });
                }
            }
            catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); }
            _lastEnumTime = DateTime.UtcNow;
        }

        public void Reset()
        {
            foreach (var a in _adapters) a.PrevTime = DateTime.MinValue;
        }
    }
}
